# Setting up your local dev server

<Steps>

### Install `frappe-react-sdk`

```bash copy
npm install frappe-react-sdk
```
or
```bash copy
yarn add frappe-react-sdk
```

### Initialising the library

To get started, initialise the library by wrapping your App with the FrappeProvider. You can optionally provide the URL of your Frappe server if the web app is not hosted on the same URL.

In `App.tsx` or `App.jsx`:

```tsx copy
import { FrappeProvider } from "frappe-react-sdk";

function App() {
    /** The URL is an optional parameter. Only use it if the Frappe server is hosted on a separate URL **/
  return (
    <FrappeProvider url='https://my-frappe-server.frappe.cloud'>
    {/** Your other app components **/}
    </FrappeProvider>
  )
}
```

In case you want to use the library with token based authentication (OAuth bearer tokens or API key/secret pairs), you can initialise the library like this:

```tsx copy
import { FrappeProvider } from "frappe-react-sdk";

function App() {

  /** The URL is an optional parameter. Only use it if the Frappe server is hosted on a separate URL **/
  return (
    <FrappeProvider url='https://my-frappe-server.frappe.cloud' tokenParams={
        useToken: true,
        // Pass a custom function that returns the token as a string - this could be fetched from LocalStorage or auth providers like Firebase, Auth0 etc.
        token: [REDACTED],
        // This can be "Bearer" or "token"
        type: "Bearer"
    } >
      {/** Your other app components **/}
    </FrappeProvider>
  );
}
```

</Steps>

# Search

## useSearch

Parameters:

| No. | Variable   | type       | Required | Description                                                                       |
| --- | ---------- | ---------- | -------- | --------------------------------------------------------------------------------- |
| 1.  | `doctype`  | `string`   | ✅       | Name of the doctype                                                               |
| 2.  | `text`     | `string`   | ✅       | Query string                                                                      |
| 3.  | `filters`  | `Filter[]` | -        | optional parameter to filter the result                                           |
| 4.  | `limit`    | `number`   | -        | the number of results to return. Defaults to 20                                   |
| 5.  | `debounce` | `number`   | -        | the number of milliseconds to wait before making the API call. Defaults to 250ms. |

```tsx copy
export const Search = () => {

  const [searchText, setSearchText] = useState('');
  const { result } = useSearch('Item', searchText);

  const handleSearchTextChange = (e) => {
    setSearchText(e.target.value);
  };

  const handleSuggestionClick = (suggestion) => {
    setSearchText(suggestion.title);
    // Perform additional action based on the selected suggestion
  };

  return (
    <div>
      <input
        type="text"
        value={searchText}
        onChange={handleSearchTextChange}
        placeholder="Search..."
      />
      {result.length > 0 && (
        <ul className="dropdown-menu">
          {result.map((item) => (
            <li key={item.id} onClick={() => handleSuggestionClick(item)}>
              {item.title}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
};
```

# DELETE

```tsx copy
export const MyDocumentDeleteCall = () => {
  const { call, result, loading, error, isCompleted, reset } = useFrappeDeleteCall(
    /** method **/
    'frappe.client.delete'
  );

  const deleteDoc = () => {
    call({
      //** params **/
      doctype: 'User',
      name: 'Administrator',
    });
  };

  const resetCall = () => {
    reset();
  };

  if (loading) {
    return <>Loading</>;
  }
  if (error) {
    return <>{JSON.stringify(error)}</>;
  }
  if (result) {
    return <p>{result}</p>;
  }
  return null;
};
```

